# -*- coding: utf-8 -*-
TITLE = "Rachunkowość, finanse przedsiębiorstwa i prawo gospodarcze"
INTRO = "Sprawozdania finansowe, zasady rachunkowości, amortyzacja i wycena, analiza wskaźnikowa, ocena inwestycji, źródła finansowania, formy prawne działalności, prawo cywilne, pracy, konsumenckie i własności intelektualnej."
E = [
 ("Rachunkowość", "System ewidencjonowania i prezentowania operacji gospodarczych jednostki (ustawa o rachunkowości z 29 września 1994 r.); dzieli się na finansową (dla odbiorców zewnętrznych) i zarządczą (dla kierownictwa).", {"k": ["rachunkowoś"]}),
 ("Sprawozdanie finansowe", "Według ustawy o rachunkowości obejmuje: bilans, rachunek zysków i strat, informację dodatkową, a w jednostkach badanych także zestawienie zmian w kapitale własnym i rachunek przepływów pieniężnych; sporządzane na dzień bilansowy.", {"k": ["sprawozdani finansow", "sprawozdanie finansowe", "sprawozdania finansowego"]}),
 ("Bilans", "Zestawienie aktywów (majątku) i pasywów (źródeł jego finansowania) na określony dzień; suma aktywów = suma pasywów.", {"k": ["bilans"]}),
 ("Aktywa trwałe i obrotowe", "Trwałe – wartości niematerialne i prawne, rzeczowe aktywa trwałe (środki trwałe, środki trwałe w budowie), należności i inwestycje długoterminowe; obrotowe – zapasy, należności krótkoterminowe, inwestycje krótkoterminowe (w tym środki pieniężne), krótkoterminowe rozliczenia międzyokresowe.", {"k": ["aktywa trwał", "aktywów trwał", "aktywa obrotow", "aktywów obrotow", "majątek trwał", "majątek obrotow", "majątku obrotow", "majątku trwał"]}),
 ("Pasywa: kapitał własny i zobowiązania", "Kapitał własny (zakładowy, zapasowy, z aktualizacji wyceny, rezerwowe, zysk/strata) oraz zobowiązania i rezerwy na zobowiązania (długo- i krótkoterminowe, rozliczenia międzyokresowe).", {"k": ["pasyw", "kapitał własn", "kapitału własn", "zobowiązan"]}),
 ("Kapitał zakładowy, zapasowy i rezerwowy", "Zakładowy – wniesiony przez właścicieli (spółka z o.o. min. 5 000 zł, S.A. min. 100 000 zł, P.S.A. min. 1 zł); zapasowy – z agio i odpisów z zysku (w S.A. obowiązkowo 8% zysku, aż osiągnie 1/3 kapitału zakładowego); rezerwowy – tworzony uchwałą na określone cele.", {"k": ["kapitał zakładow", "kapitału zakładow", "kapitał zapasow", "kapitału zapasow", "kapitał rezerwow"]}),
 ("Kapitał stały i obrotowy netto", "Kapitał stały = kapitał własny + zobowiązania długoterminowe. Kapitał obrotowy netto = kapitał stały − aktywa trwałe (= aktywa obrotowe − zobowiązania krótkoterminowe).", {"k": ["kapitał stał", "kapitału stał", "kapitał obrotow", "kapitału obrotow"]}),
 ('Złota reguła bilansowa', 'Aktywa trwałe powinny być w pełni finansowane kapitałem własnym (lub stałym); srebrna reguła – kapitałem stałym. Wskaźniki: złota reguła bilansowa – KW / MT ≥ 1; srebrna – kapitał stały / MT ≥ 1 (kapitał stały = KW + zobowiązania długoterminowe). Spełnienie oznacza mocne podstawy kapitałowe i niezależność finansową.', {'k': ['złota reguł bilansow', 'złota reguła bilansowa', 'złotej reguły bilansowej', 'srebrn reguł', 'srebrn reguł', 'srebrna reguła', 'srebrna zasada', 'złota zasada bilansowa']}),
 ("Rozliczenia międzyokresowe", "Czynne – koszty poniesione z góry, dotyczące przyszłych okresów (np. czynsz zapłacony z góry, prenumerata) – aktywa; bierne – koszty przyszłe dotyczące bieżącego okresu (rezerwy, np. na urlopy) – pasywa.", {"k": ["rozliczenia międzyokresow", "rozliczeń międzyokresow", "rozliczenia międzyokresowe"]}),
 ("Rachunek zysków i strat (RZiS)", "Zestawienie przychodów i kosztów oraz wyniku finansowego za okres. Wariant porównawczy (koszty według rodzaju) lub kalkulacyjny (koszty według funkcji – koszt własny sprzedaży, koszty sprzedaży, ogólnego zarządu).", {"k": ["rachunek zysków i strat", "rachunku zysków i strat", "rzis", "wariant porównawcz", "wariant kalkulacyjn", "układzie kalkulacyjnym"]}),
 ("Wynik finansowy – poziomy", "Wynik ze sprzedaży → wynik z działalności operacyjnej (EBIT) → wynik brutto (po przychodach i kosztach finansowych) → wynik netto (po podatku dochodowym).", {"k": ["zysk brutto", "zysk netto", "zysku netto", "wynik finansow", "wyniku finansow", "ebit", "zysk operacyjn", "zysku operacyjn", "wynik z działalności operacyjnej", "wyniku z działalności operacyjnej", "zysk ze sprzedaży", "zysku ze sprzedaży"]}),
 ("EBITDA", "Zysk operacyjny przed odliczeniem odsetek, podatków i amortyzacji – przybliżenie operacyjnych przepływów pieniężnych.", {"k": ["ebitda"]}),
 ("Rachunek przepływów pieniężnych (cash flow)", "Zestawienie wpływów i wydatków środków pieniężnych w podziale na działalność operacyjną, inwestycyjną i finansową; metoda bezpośrednia lub pośrednia.", {"k": ["przepływ pieniężn", "przepływów pieniężn", "przepływy pieniężn", "cash flow"]}),
 ("Zasady rachunkowości", "Memoriałowa (przychody i koszty w okresie, którego dotyczą, niezależnie od zapłaty), współmierności (koszty łączy się z przychodami, które przyniosły), ostrożności (wycena z ostrożnością, ujmowanie przewidywanych strat), kontynuacji działalności, ciągłości, istotności, wiernego i rzetelnego obrazu, przewagi treści nad formą, periodyzacji, kosztu historycznego.", {"k": ["zasad memoriałow", "zasada memoriałowa", "zasady memoriałowej", "współmiernoś", "ostrożnoś", "kontynuacji działalności", "periodyzacj", "zasady rachunkowości", "zasad rachunkowości", "zasada kasowa"]}),
 ("Polityka rachunkowości", "Wybrane i stosowane przez jednostkę rozwiązania dopuszczone ustawą: rok obrotowy, metody wyceny aktywów i pasywów, sposób prowadzenia ksiąg (zakładowy plan kont), opis systemu informatycznego.", {"k": ["polityk rachunkowości", "polityka rachunkowości"]}),
 ("Rok obrotowy", "Rok kalendarzowy lub inny okres trwający 12 miesięcy, za który sporządza się sprawozdanie finansowe.", {"k": ["rok obrotow", "roku obrotow"]}),
 ("Księgi rachunkowe i konta", "Dziennik, księga główna, księgi pomocnicze, zestawienie obrotów i sald, inwentarz. Konto księgowe ma stronę Winien (debet) i Ma (kredyt); zasada podwójnego zapisu – każda operacja zapisywana jest na dwóch kontach po przeciwnych stronach.", {"k": ["księg", "winien", "debet", "podwójnego zapisu", "zapis po stronie"]}),
 ("Operacje bilansowe", "Cztery typy zmian: aktywa–aktywa (zmiana struktury aktywów, np. wpłata gotówki z kasy na rachunek), pasywa–pasywa, aktywa–pasywa zwiększające sumę bilansową (np. zakup na kredyt), aktywa–pasywa zmniejszające (np. spłata zobowiązania).", {"k": ["sum bilansow", "suma bilansowa", "sumy bilansowej", "operacj bilansow"]}),
 ("Inwentaryzacja", "Ustalenie rzeczywistego stanu aktywów i pasywów (spis z natury, potwierdzenie sald, weryfikacja) i porównanie z księgami.", {"k": ["inwentaryzacj"]}),
 ("Uproszczone formy ewidencji", "Księga przychodów i rozchodów (KPiR), ewidencja przychodów (ryczałt), karta podatkowa – dla mniejszych przedsiębiorców; pełne księgi obowiązkowe m.in. dla spółek kapitałowych i przy przychodach powyżej 2 mln euro.", {"k": ["księga przychodów", "kpir", "karta podatkow", "karty podatkow", "ryczałt"]}),
 ("Środki trwałe", "Rzeczowe aktywa o przewidywanym okresie używania dłuższym niż rok, kompletne i zdatne do użytku, przeznaczone na potrzeby jednostki (budynki, maszyny, środki transportu, grunty).", {"k": ["środk trwał", "środki trwałe", "środków trwałych", "środkiem trwałym"]}),
 ("Wartości niematerialne i prawne", "Nabyte prawa majątkowe (licencje, patenty, prawa autorskie, know-how, oprogramowanie) i wartość firmy, wykorzystywane przez okres dłuższy niż rok.", {"k": ["wartości niematerialn", "wartość niematerialn"]}),
 ("Wartość firmy (goodwill)", "Nadwyżka ceny nabycia jednostki nad wartością godziwą jej aktywów netto – odzwierciedla m.in. reputację, relacje z klientami, markę.", {"k": ["goodwill", "wartość firmy", "wartości firmy"]}),
 ("Amortyzacja", "Systematyczne rozłożenie wartości początkowej środka trwałego lub wartości niematerialnej na okres jego użytkowania; koszt niepieniężny. Nie amortyzuje się gruntów (poza prawem użytkowania wieczystego w podatkach) ani dzieł sztuki.", {"k": ["amortyz"]}),
 ("Metody amortyzacji", "Liniowa (równe odpisy), degresywna (odpisy malejące – stawka liniowa × współczynnik od wartości netto), jednorazowa, naturalna (proporcjonalna do produkcji).", {"w": "liniowa: odpis roczny = wartość początkowa × stawka (lub (WP − wartość końcowa) / okres)", "k": ["liniow amortyz", "metoda liniowa", "degresywn"]}),
 ("Wycena zapasów (rozchodu)", "FIFO – pierwsze weszło, pierwsze wyszło; LIFO – ostatnie weszło, pierwsze wyszło (niedozwolone w MSSF); średnia ważona (AVCO); szczegółowa identyfikacja. Przy rosnących cenach FIFO daje wyższy zysk.", {"k": ["fifo", "lifo", "avco", "hifo", "wycen zapas", "wycena zapasów"]}),
 ("Wartość godziwa i koszt historyczny", "Godziwa – kwota, za jaką składnik mógłby zostać wymieniony między dobrze poinformowanymi stronami; historyczny – cena nabycia lub koszt wytworzenia.", {"k": ["wartość godziw", "wartości godziw", "koszt historyczn", "ceny historyczn", "cen nabycia", "cena nabycia"]}),
 ("Koszty według rodzajów", "Amortyzacja, zużycie materiałów i energii, usługi obce, podatki i opłaty, wynagrodzenia, ubezpieczenia społeczne i inne świadczenia, pozostałe koszty rodzajowe.", {"k": ["koszty według rodzaj", "kosztów rodzajow", "koszty rodzajow", "rodzajow"]}),
 ("Koszty bezpośrednie i pośrednie", "Bezpośrednie – można przypisać do konkretnego produktu (materiały bezpośrednie, płace bezpośrednie); pośrednie – wspólne dla wielu produktów (koszty wydziałowe, ogólnego zarządu), rozliczane kluczami.", {"k": ["koszty bezpośredni", "koszty pośredni", "kosztów pośredni", "kosztów bezpośredni", "koszt pośredni"]}),
 ("Rachunek kosztów pełnych i zmiennych", "Pełnych – koszt jednostkowy obejmuje wszystkie koszty wytworzenia; zmiennych (rachunek marży) – produkty obciąża się tylko kosztami zmiennymi, a stałe pokrywa się z marży.", {"k": ["rachunek kosztów", "rachunku kosztów", "marż pokrycia", "marża pokrycia"]}),
 ("Rachunek kosztów działań (ABC)", "Activity-Based Costing – przypisywanie kosztów pośrednich do produktów według działań i nośników kosztów, które je powodują.", {"k": ["kosztów działań", "activity-based", "abc"]}),
 ("Analiza wskaźnikowa", "Ocena kondycji firmy na podstawie relacji pozycji sprawozdań: wskaźniki płynności, rentowności, zadłużenia, sprawności (rotacji), rynkowe.", {"k": ["analiz wskaźnikow", "analiza wskaźnikowa", "wskaźnik"]}),
 ("Wskaźniki płynności", "Bieżącej płynności = aktywa obrotowe / zobowiązania krótkoterminowe (zalecane 1,2–2); szybkiej płynności = (aktywa obrotowe − zapasy) / zobowiązania krótkoterminowe (ok. 1); gotówkowy = środki pieniężne / zobowiązania krótkoterminowe.", {"k": ["płynnoś"]}),
 ("Wskaźniki rentowności (ROA, ROE, ROS)", "ROA = zysk netto / aktywa; ROE = zysk netto / kapitał własny; ROS = zysk netto / przychody ze sprzedaży. Analiza Du Ponta rozkłada ROE na rentowność sprzedaży, rotację aktywów i mnożnik kapitałowy.", {"w": "ROE = ROS × (przychody/aktywa) × (aktywa/kapitał własny)", "k": ["roa", "roe", "ros", "rentownoś", "du pont"]}),
 ("Wskaźniki zadłużenia", "Ogólnego zadłużenia = zobowiązania / aktywa; zadłużenia kapitału własnego = zobowiązania / kapitał własny; pokrycia odsetek = EBIT / odsetki; pokrycia długu nadwyżką finansową = (zysk netto + amortyzacja) / (raty + odsetki).", {"k": ["zadłużeni", "pokrycia"]}),
 ("Wskaźniki rotacji (sprawności)", "Rotacja aktywów = przychody / aktywa (ile razy w roku aktywa „obracają się”); rotacja należności w dniach = należności / przychody × 365; rotacja zapasów; rotacja zobowiązań; cykl konwersji gotówki = rotacja zapasów + rotacja należności − rotacja zobowiązań.", {"k": ["rotacj", "cykl konwersji"]}),
 ("Dźwignia operacyjna i finansowa (DOL, DFL)", "Operacyjna – wrażliwość zysku operacyjnego na zmianę sprzedaży (wynika z kosztów stałych); finansowa – wrażliwość zysku netto/ROE na zmianę EBIT (wynika z kosztów długu). Dodatni efekt dźwigni finansowej, gdy rentowność aktywów przewyższa koszt długu.", {"k": ["dźwignia operacyjn", "dźwigni operacyjn", "dźwignia finansow", "dźwigni finansow", "dol", "dfl"]}),
 ("Średni ważony koszt kapitału (WACC)", "Średni koszt kapitału własnego i obcego ważony ich udziałem w finansowaniu (koszt długu po uwzględnieniu tarczy podatkowej).", {"w": "WACC = wE·kE + wD·kD·(1 − T)", "k": ["wacc", "koszt kapitału", "kosztu kapitału"]}),
 ("Wartość bieżąca netto (NPV)", "Suma zdyskontowanych przepływów pieniężnych projektu minus nakład początkowy; NPV > 0 – projekt opłacalny.", {"w": "NPV = Σ CFₜ / (1 + r)ᵗ − I₀", "k": ["npv", "wartość bieżąca netto", "wartości bieżącej netto"]}),
 ("Wewnętrzna stopa zwrotu (IRR) i MIRR", "IRR – stopa dyskontowa, przy której NPV = 0; projekt opłacalny, gdy IRR > koszt kapitału. MIRR – zmodyfikowana IRR zakładająca reinwestycję przepływów po koszcie kapitału.", {"k": ["irr", "mirr", "wewnętrzn stop", "wewnętrzna stopa"]}),
 ("Okres zwrotu", "Czas, po którym skumulowane przepływy pieniężne pokryją nakład inwestycyjny (prosty lub zdyskontowany).", {"k": ["okres zwrotu", "okresu zwrotu"]}),
 ("Źródła finansowania przedsiębiorstwa", "Wewnętrzne (zysk zatrzymany, amortyzacja, sprzedaż majątku) i zewnętrzne – kapitał własny (emisja akcji, udziały, venture capital) oraz obcy (kredyt bankowy, pożyczka, obligacje, leasing, faktoring, kredyt kupiecki, dotacje, crowdfunding).", {"k": ["źródł finansowania", "źródła finansowania", "źródłem finansowania", "finansowani wewnętrzn", "finansowania zewnętrzn"]}),
 ("Kredyt kupiecki (handlowy)", "Odroczenie terminu zapłaty za towar przez dostawcę – dla nabywcy źródło finansowania krótkoterminowego (zobowiązanie handlowe).", {"k": ["kredyt kupieck", "kredytu kupieck", "kredyt handlow"]}),
 ("Kredyt obrotowy i inwestycyjny", "Obrotowy – na finansowanie bieżącej działalności (zapasy, należności), np. w rachunku bieżącym lub odnawialny; inwestycyjny – na zakup środków trwałych i projekty długoterminowe.", {"k": ["kredyt obrotow", "kredyty obrotow", "kredytów obrotow", "kredyt inwestycyjn", "kredytów inwestycyjn", "kredyty inwestycyjn"]}),
 ("Zabezpieczenia kredytu", "Osobiste (poręczenie, weksel, gwarancja) i rzeczowe (hipoteka, zastaw rejestrowy, przewłaszczenie na zabezpieczenie, cesja wierzytelności, kaucja).", {"k": ["zabezpieczeni kredyt", "zabezpieczenia kredytu", "przewłaszczen", "cesj", "poręczeni", "zastaw"]}),
 ("Gwarancje de minimis", "Gwarancje kredytów udzielane małym i średnim firmom przez Bank Gospodarstwa Krajowego w ramach pomocy publicznej de minimis (do 300 000 euro w ciągu 3 lat od 2024 r.; wcześniej 200 000 euro).", {"k": ["de minimis"]}),
 ("Crowdfunding", "Finansowanie społecznościowe – zbieranie środków od wielu drobnych inwestorów lub darczyńców przez internet (udziałowy, pożyczkowy, nagrodowy, donacyjny).", {"k": ["crowdfunding", "społecznościow"]}),
 ("Project finance", "Finansowanie przedsięwzięcia, w którym spłata długu następuje głównie z przepływów generowanych przez sam projekt (spółka celowa).", {"k": ["project finance"]}),
 ("Należności i zobowiązania", "Należności – kwoty, które firma ma otrzymać od kontrahentów; zobowiązania – kwoty do zapłacenia. Zatory płatnicze – opóźnienia w regulowaniu zobowiązań.", {"k": ["należnoś", "zator"]}),
 ("Upadłość i restrukturyzacja", "Upadłość – postępowanie wobec niewypłacalnego dłużnika (prawo upadłościowe, 2003 r.) mające zaspokoić wierzycieli; restrukturyzacja (prawo restrukturyzacyjne, 2015 r.) – postępowania naprawcze (np. układ z wierzycielami), by uniknąć upadłości. Upadłość konsumencka dla osób fizycznych. Postępowanie prowadzi sąd upadłościowy, nadzoruje je sędzia-komisarz, a majątkiem upadłego zarządza i spienięża go syndyk; egzekucję pojedynczych należności poza upadłością prowadzi komornik.", {"k": ["upadłoś", "restrukturyzac", "niewypłacaln", "syndyk", "sędzi komisarz", "sędzia-komisarz", "sędziego-komisarza", "komornik"]}),
 ("Przedsiębiorca i działalność gospodarcza", "Działalność gospodarcza – zorganizowana działalność zarobkowa wykonywana we własnym imieniu i w sposób ciągły (Prawo przedsiębiorców z 6 marca 2018 r.). Działalność nierejestrowana – przychód do 75% minimalnego wynagrodzenia miesięcznie (od 2026 r. limit kwartalny 225%).", {"u": "limit działalności nierejestrowanej zmieniony na kwartalny od 1 stycznia 2026 r.", "k": ["przedsiębiorc", "działalnoś gospodarcz", "działalność gospodarcza", "działalności gospodarczej", "nierejestrowan"]}),
 ("Konstytucja biznesu (2018)", "Pakiet ustaw z 2018 r. (m.in. Prawo przedsiębiorców): zasada „co nie jest prawem zabronione, jest dozwolone”, domniemanie uczciwości przedsiębiorcy, rozstrzyganie wątpliwości na korzyść przedsiębiorcy, ulga na start, Rzecznik MŚP.", {"k": ["konstytucj biznesu", "konstytucja biznesu", "prawo przedsiębiorców", "ulga na start"]}),
 ("CEIDG i KRS", "CEIDG – Centralna Ewidencja i Informacja o Działalności Gospodarczej (jednoosobowe działalności i wspólnicy spółek cywilnych); KRS – Krajowy Rejestr Sądowy (spółki handlowe, fundacje, stowarzyszenia), prowadzony przez sądy rejonowe. Numery identyfikacyjne: NIP (podatkowy), REGON (statystyczny), KRS.", {"k": ["ceidg", "krs", "krajow rejestr sądow", "nip", "regon"]}),
 ("Jednoosobowa działalność gospodarcza", "Najprostsza forma działalności osoby fizycznej; przedsiębiorca odpowiada całym majątkiem.", {"k": ["jednoosobow działalnoś", "jednoosobowa działalność", "jednoosobowej działalności"]}),
 ("Spółka cywilna", "Umowa wspólników (kodeks cywilny), nie jest przedsiębiorcą ani osobą prawną (przedsiębiorcami są wspólnicy); wspólnicy odpowiadają solidarnie całym majątkiem.", {"k": ["spółk cywiln", "spółka cywilna", "spółki cywilnej"]}),
 ("Spółki osobowe (KSH)", "Spółka jawna (wspólnicy odpowiadają bez ograniczeń, subsydiarnie), partnerska (wolne zawody; partner nie odpowiada za błędy innych partnerów), komandytowa (komplementariusz – bez ograniczeń, komandytariusz – do sumy komandytowej), komandytowo-akcyjna (komplementariusz – bez ograniczeń, akcjonariusze – nie odpowiadają; ma kapitał zakładowy min. 50 000 zł).", {"k": ["spółk jawn", "spółka jawna", "spółki jawnej", "partnersk", "komandyt", "spółki osobow", "spółek osobow", "spółka osobowa"]}),
 ("Spółki kapitałowe (KSH)", "Spółka z ograniczoną odpowiedzialnością (kapitał min. 5 000 zł, organy: zarząd, zgromadzenie wspólników, ewentualnie rada nadzorcza), spółka akcyjna (min. 100 000 zł; zarząd, rada nadzorcza, walne zgromadzenie), prosta spółka akcyjna (od 1 lipca 2021 r., kapitał akcyjny min. 1 zł, zarząd lub rada dyrektorów). Mają osobowość prawną; wspólnicy co do zasady nie odpowiadają za zobowiązania spółki.", {"k": ["spółk kapitałow", "spółki kapitałow", "spółek kapitałow", "spółka kapitałowa", "z ograniczoną odpowiedzialnością", "spółka z o.o.", "spółk akcyjn", "spółka akcyjna", "spółki akcyjnej", "prosta spółka akcyjna", "prostej spółki akcyjnej", "p.s.a"]}),
 ("Organy spółki akcyjnej", "Zarząd (prowadzi sprawy i reprezentuje spółkę), rada nadzorcza (stały nadzór), walne zgromadzenie (najważniejsze decyzje: zatwierdzenie sprawozdań, podział zysku, absolutorium, zmiana statutu).", {"k": ["walne zgromadzeni", "walnego zgromadzeni", "rada nadzorcz", "rady nadzorcz", "radę nadzorcz", "zarząd spółki", "zgromadzenie wspólników"]}),
 ("Prokura", "Pełnomocnictwo handlowe udzielane przez przedsiębiorcę wpisanego do KRS lub CEIDG, obejmujące umocowanie do czynności związanych z prowadzeniem przedsiębiorstwa (z wyjątkiem m.in. zbycia przedsiębiorstwa i nieruchomości bez szczególnego pełnomocnictwa); nie można jej przenieść.", {"k": ["prokur"]}),
 ("Osoba fizyczna, prawna i jednostka organizacyjna", "Osoba fizyczna – człowiek; osoba prawna – Skarb Państwa i jednostki, którym ustawa przyznaje osobowość prawną (spółki kapitałowe, spółdzielnie, fundacje, stowarzyszenia rejestrowe); ułomne osoby prawne – jednostki bez osobowości, którym ustawa przyznaje zdolność prawną (spółki osobowe).", {"k": ["osob prawn", "osoba prawna", "osobowość prawn", "osobowości prawn"]}),
 ("Zdolność prawna i zdolność do czynności prawnych", "Zdolność prawna – zdolność do bycia podmiotem praw i obowiązków (od urodzenia); zdolność do czynności prawnych: pełna od 18 lat (lub zawarcia małżeństwa), ograniczona 13–18 lat, brak poniżej 13 lat i u ubezwłasnowolnionych całkowicie.", {"k": ["zdolność prawn", "zdolności prawn", "zdolność do czynności", "zdolności do czynności"]}),
 ("Spółdzielnia", "Dobrowolne zrzeszenie nieograniczonej liczby osób o zmiennym składzie i kapitale, prowadzące wspólną działalność gospodarczą w interesie członków (prawo spółdzielcze 1982 r.).", {"k": ["spółdzielni"]}),
 ("Przedsiębiorstwo państwowe i Skarb Państwa", "Przedsiębiorstwo państwowe – samodzielna jednostka gospodarcza z mieniem państwowym (forma wygasająca); Skarb Państwa – osoba prawna reprezentująca państwo w stosunkach majątkowych; komercjalizacja – przekształcenie przedsiębiorstwa państwowego w spółkę Skarbu Państwa; prywatyzacja – zbycie udziałów inwestorom prywatnym.", {"k": ["przedsiębiorstw państwow", "skarb państwa", "skarbu państwa", "komercjalizacj", "prywatyzacj"]}),
 ("Fundacja i stowarzyszenie", "Fundacja – majątek przeznaczony przez fundatora na cel społecznie lub gospodarczo użyteczny; stowarzyszenie – dobrowolne, samorządne zrzeszenie osób o celach niezarobkowych. Fundacja rodzinna (od 2023 r.) – służy sukcesji majątku.", {"k": ["fundacj", "stowarzysz"]}),
 ("Umowy w kodeksie cywilnym", "Sprzedaż, zamiana, darowizna, najem (rzeczy do używania), dzierżawa (do używania i pobierania pożytków), użyczenie (bezpłatne), pożyczka, leasing, zlecenie, umowa o dzieło (rezultat), umowa agencyjna, komisu, przewozu, spedycji, rachunku bankowego.", {"k": ["umow sprzedaży", "umowa sprzedaży", "najem", "najm", "dzierżaw", "użyczeni", "pożyczk", "zleceni", "umow o dzieło", "umowa o dzieło", "umowy o dzieło", "komis"]}),
 ("Umowa o pracę i umowy cywilnoprawne", "Umowa o pracę (Kodeks pracy) – na okres próbny (do 3 miesięcy), na czas określony (łącznie do 33 miesięcy i max 3 umowy), na czas nieokreślony; daje pełne prawa pracownicze. Umowa zlecenie (staranne działanie, minimalna stawka godzinowa) i umowa o dzieło (określony rezultat) – umowy cywilnoprawne.", {"k": ["umow o pracę", "umowa o pracę", "umowy o pracę", "umowę o pracę", "kodeks pracy", "kodeksu pracy", "umowa zleceni", "umowy zleceni"]}),
 ("Prawa i obowiązki pracownicze", "Urlop wypoczynkowy 20 dni (staż < 10 lat) lub 26 dni; okresy wypowiedzenia umowy na czas nieokreślony: 2 tygodnie, 1 miesiąc, 3 miesiące (zależnie od stażu); czas pracy do 8 h na dobę i przeciętnie 40 h w tygodniu; ochrona przed mobbingiem i dyskryminacją; odpowiedzialność materialna pracownika.", {"k": ["urlop", "wypowiedzeni", "czas pracy", "czasu pracy"]}),
 ("Mobbing", "Działania lub zachowania dotyczące pracownika lub skierowane przeciwko niemu, polegające na uporczywym i długotrwałym nękaniu lub zastraszaniu, wywołujące zaniżoną ocenę przydatności zawodowej, poniżenie, izolowanie (art. 94³ Kodeksu pracy).", {"k": ["mobbing"]}),
 ("Sygnalista", "Osoba zgłaszająca naruszenia prawa w organizacji; chroniona ustawą o ochronie sygnalistów (od 25 września 2024 r.).", {"k": ["sygnalist"]}),
 ("Prawa konsumenta", "Prawo odstąpienia od umowy zawartej na odległość lub poza lokalem przedsiębiorstwa w ciągu 14 dni bez podania przyczyny; rękojmia za wady (2 lata od wydania rzeczy; od 2023 r. odpowiedzialność za brak zgodności towaru z umową); gwarancja – dobrowolne zobowiązanie gwaranta; ochrona przed klauzulami niedozwolonymi.", {"k": ["konsument", "rękojm", "gwarancj", "odstąpieni"]}),
 ("Urząd Ochrony Konkurencji i Konsumentów (UOKiK)", "Organ ochrony konkurencji i konsumentów: zakazuje porozumień ograniczających konkurencję (zmowy cenowe, przetargowe, podział rynku, narzucanie cen odsprzedaży) i nadużywania pozycji dominującej, kontroluje koncentracje, nakłada kary do 10% obrotu, prowadzi rejestr klauzul niedozwolonych (dawniej).", {"k": ["uokik", "ochrony konkurencji", "praktyk ograniczając", "zmow", "pozycj dominując", "pozycji dominującej"]}),
 ("Nieuczciwa konkurencja", "Działanie sprzeczne z prawem lub dobrymi obyczajami, zagrażające interesowi innego przedsiębiorcy lub klienta (ustawa z 1993 r.), np. wprowadzające w błąd oznaczenie, naruszenie tajemnicy przedsiębiorstwa, nakłanianie do niewykonania umowy, nieuczciwa reklama.", {"k": ["nieuczciw konkurencj", "nieuczciwa konkurencja", "nieuczciwej konkurencji"]}),
 ("Własność intelektualna", "Prawa autorskie (utwory – ochrona majątkowa do 70 lat po śmierci autora) i prawa własności przemysłowej (Prawo własności przemysłowej, Urząd Patentowy RP): patent na wynalazek (20 lat), prawo ochronne na wzór użytkowy (10 lat) i znak towarowy (10 lat, odnawialne), prawo z rejestracji wzoru przemysłowego (do 25 lat), oznaczenia geograficzne, topografie układów scalonych.", {"k": ["własnoś intelektualn", "własności intelektualnej", "własności przemysłow", "patent", "znak towarow", "znaki towarow", "wzór przemysłow", "wzory przemysłow", "wzór użytkow", "prawa autorsk", "prawo autorsk"]}),
 ("Licencja i know-how", "Licencja – zgoda uprawnionego na korzystanie z prawa (patentu, utworu, znaku) przez inną osobę; know-how – nieopatentowana wiedza techniczna i organizacyjna o wartości gospodarczej.", {"k": ["licencj", "know-how"]}),
 ("Franczyza (franchising)", "Umowa, w której franczyzodawca udostępnia franczyzobiorcy markę, know-how i system prowadzenia działalności w zamian za opłaty (wstępną i bieżące).", {"k": ["franczyz", "franchis"]}),
 ("Hipoteka", "Ograniczone prawo rzeczowe obciążające nieruchomość (lub użytkowanie wieczyste) w celu zabezpieczenia wierzytelności; wpisywana do księgi wieczystej; może zabezpieczać wierzytelności przyszłe i kilka nieruchomości (hipoteka łączna).", {"k": ["hipotek"]}),
 ("Księga wieczysta", "Publiczny rejestr prowadzony przez sądy rejonowe, ustalający stan prawny nieruchomości (właściciel, ograniczone prawa rzeczowe, hipoteki); od 2016 r. w formie elektronicznej.", {"k": ["księg wieczyst", "księga wieczysta", "księgi wieczystej"]}),
 ("Własność i ograniczone prawa rzeczowe", "Własność – najszersze prawo do rzeczy (używanie, pobieranie pożytków, rozporządzanie); użytkowanie wieczyste – prawo do gruntu Skarbu Państwa/JST na 40–99 lat; ograniczone prawa rzeczowe: użytkowanie, służebności, zastaw, hipoteka, spółdzielcze prawo do lokalu.", {"k": ["użytkowani wieczyst", "użytkowanie wieczyste", "użytkowaniu wieczystym", "służebnoś", "prawo własności", "prawa rzeczow"]}),
 ("Przedawnienie roszczeń", "Upływ terminu, po którym dłużnik może uchylić się od zaspokojenia roszczenia. Ogólny termin (od 2018 r.) – 6 lat, dla świadczeń okresowych i związanych z działalnością gospodarczą – 3 lata; koniec biegu przypada na ostatni dzień roku kalendarzowego.", {"k": ["przedawn"]}),
 ("Odpowiedzialność kontraktowa i deliktowa", "Kontraktowa – za niewykonanie lub nienależyte wykonanie zobowiązania (umowy); deliktowa – za szkodę wyrządzoną czynem niedozwolonym (z winy, na zasadzie ryzyka).", {"k": ["odpowiedzialnoś deliktow", "odpowiedzialność deliktowa", "odpowiedzialnoś kontraktow", "czyn niedozwolon"]}),
 ("Kara umowna i zadatek", "Kara umowna – zastrzeżona w umowie suma za niewykonanie zobowiązania niepieniężnego; zadatek – kwota wręczona przy zawarciu umowy, przepadająca na rzecz drugiej strony, gdy wręczający nie wykona umowy (a w odwrotnej sytuacji zwracana w podwójnej wysokości).", {"k": ["kara umown", "kary umown", "zadat"]}),
 ("Corporate governance (ład korporacyjny)", "Zasady nadzoru i zarządzania spółkami chroniące interesy akcjonariuszy i innych interesariuszy; na GPW – „Dobre Praktyki Spółek Notowanych” (comply or explain).", {"k": ["corporate governance", "ład korporacyjn", "ładu korporacyjn", "dobre praktyki"]}),
 ("Audyt wewnętrzny i biegły rewident", "Audyt wewnętrzny – niezależna ocena systemów kontroli i zarządzania w organizacji; biegły rewident – zawód zaufania publicznego badający sprawozdania finansowe (nadzór PANA).", {"k": ["audyt", "biegł rewident", "biegły rewident", "biegłego rewidenta"]}),
 ("RODO", "Rozporządzenie UE o ochronie danych osobowych (stosowane od 25 maja 2018 r.); organ nadzorczy w Polsce – Prezes Urzędu Ochrony Danych Osobowych.", {"k": ["rodo", "danych osobowych"]}),
 ("Mała, średnia i mikrofirma (MŚP)", "Według Prawa przedsiębiorców/UE: mikro – do 10 pracowników i obrót do 2 mln euro; mały – do 50 i do 10 mln euro; średni – do 250 pracowników i obrót do 50 mln euro (lub suma bilansowa do 43 mln euro).", {"k": ["mśp", "mikroprzedsiębior", "małe i średnie", "małych i średnich", "mikrofirm", "średni przedsiębior"]}),
 ('Cel finansowy przedsiębiorstwa – maksymalizacja wartości', 'We współczesnych finansach celem jest wzrost wartości przedsiębiorstwa dla właścicieli (shareholder value), a nie samego zysku bieżącego; koncepcja interesariuszy (stakeholder value) uwzględnia też pracowników, klientów, wierzycieli i społeczność.', {'k': ['wartości przedsiębiorstwa', 'wartość przedsiębiorstwa', 'shareholder', 'wartość dla akcjonariuszy', 'wartości dla właścicieli', 'maksymalizacj wartości']}),
 ('EVA (ekonomiczna wartość dodana)', 'Miara tworzenia wartości: zysk operacyjny po opodatkowaniu pomniejszony o koszt całego zaangażowanego kapitału; EVA > 0 oznacza, że firma zarabia więcej niż koszt kapitału.', {'w': 'EVA = NOPAT − WACC · kapitał zaangażowany', 'k': ['eva', 'ekonomiczn wartoś dodan', 'nopat']}),
 ('Struktura kapitału i teorie jej wyboru', 'Proporcja kapitału własnego i obcego. Twierdzenia Modiglianiego–Millera (1958): bez podatków struktura nie wpływa na wartość firmy; z podatkami dług zwiększa wartość dzięki tarczy podatkowej. Teoria kompromisu (trade-off) – korzyści podatkowe vs koszty trudności finansowych; teoria hierarchii źródeł (pecking order, S. Myers) – najpierw środki własne, potem dług, na końcu emisja akcji.', {'k': ['struktur kapitału', 'struktura kapitału', 'struktury kapitału', 'modigliani', 'pecking', 'hierarchii źródeł', 'teori kompromis', 'trade-off']}),
 ('Koszt kapitału własnego i obcego', 'Koszt kapitału obcego – oprocentowanie długu skorygowane o tarczę podatkową: kd·(1 − T). Koszt kapitału własnego – wymagana stopa zwrotu akcjonariuszy, liczona modelem CAPM lub modelem Gordona (stałego wzrostu dywidendy). Najprostsza metoda: koszt kapitału własnego = stopa wolna od ryzyka (rentowność obligacji skarbowych) + premia za ryzyko (historyczna nadwyżka stopy zwrotu z akcji nad obligacjami).', {'w': 'Gordon: ke = D₁ / P₀ + g;  CAPM: ke = Rf + β(Rm − Rf)', 'k': ['koszt kapitał własn', 'koszt kapitału własnego', 'koszt kapitał obc', 'koszt długu', 'gordon', 'premi za ryzyko', 'stopa wolna od ryzyka']}),
 ('Model Gordona (wycena akcji)', 'Wartość akcji jako zdyskontowany strumień dywidend rosnących w stałym tempie g.', {'w': 'P₀ = D₁ / (k − g)', 'p': 'D₁ = 4 zł, k = 10%, g = 2% ⇒ P₀ = 4 / 0,08 = 50 zł.', 'k': ['model gordona', 'modelu gordona', 'stałego wzrostu dywidend']}),
 ('Planowanie finansowe i budżet kasowy', 'Planowanie finansowe – prognozowanie sprawozdań (bilansu, RZiS, przepływów) i potrzeb kapitałowych (np. metoda procentu od sprzedaży); budżet kasowy (preliminarz) – plan wpływów i wydatków gotówkowych w krótkich okresach, pozwalający przewidzieć niedobory i nadwyżki gotówki.', {'k': ['planowani finansow', 'planowanie finansowe', 'budżet kasow', 'budżetu kasow', 'preliminarz', 'procentu od sprzedaży']}),
 ('Zarządzanie kapitałem obrotowym', 'Zarządzanie zapasami, należnościami (polityka kredytu kupieckiego, windykacja, faktoring), środkami pieniężnymi (model Baumola, model Millera–Orra, cash pooling) i zobowiązaniami bieżącymi. Strategie finansowania: agresywna (dużo krótkoterminowego długu – tańsza, ryzykowniejsza), konserwatywna (kapitał stały finansuje też część aktywów obrotowych), umiarkowana.', {'k': ['kapitał obrotow', 'kapitałem obrotowym', 'zarządzani należnościami', 'zarządzanie należnościami', 'zarządzani gotówką', 'zarządzanie gotówką', 'strategi agresywn', 'strategia agresywna', 'konserwatywn', 'cash pooling', 'miller–orr', 'windykac']}),
 ('Cykl operacyjny i cykl konwersji gotówki', 'Cykl operacyjny = cykl zapasów + cykl należności (czas od zakupu materiałów do wpływu gotówki ze sprzedaży); cykl konwersji gotówki = cykl operacyjny − cykl zobowiązań.', {'w': 'CKG = rotacja zapasów + rotacja należności − rotacja zobowiązań (w dniach)', 'k': ['cykl operacyjn', 'cyklu operacyjn']}),
 ('Ocena projektów inwestycyjnych – metody', 'Metody proste (statyczne): okres zwrotu, księgowa stopa zwrotu; dyskontowe (dynamiczne): NPV, IRR, MIRR, wskaźnik rentowności PI = PV wpływów / nakład, zdyskontowany okres zwrotu. Ryzyko projektu bada się analizą wrażliwości, scenariuszy i progu rentowności.', {'k': ['ocen projekt', 'ocena projektów', 'budżetowani kapitałow', 'budżetowanie kapitałowe', 'analiz wrażliwości', 'analiza wrażliwości', 'księgow stop zwrotu', 'wskaźnik rentowności pi', 'pi =']}),
 ('Emisja papierów wartościowych – przebieg', 'Uchwała o emisji, wybór trybu (oferta publiczna z prospektem lub prywatna – do ograniczonego kręgu inwestorów), wycena i book-building, gwarancja emisji (underwriting – subemitent przejmuje niesprzedane papiery), zapisy i przydział, rejestracja w KDPW, wprowadzenie do obrotu.', {'k': ['emisj papierów', 'emisja papierów', 'emisji papierów', 'underwriting', 'subemitent', 'oferta prywatn', 'ofert prywatn', 'book-building', 'gwarant emisji']}),
 ('Finansowanie mezzanine i kredyt rewolwingowy', 'Mezzanine – finansowanie hybrydowe między długiem a kapitałem (np. pożyczka podporządkowana z opcją zamiany na udziały); kredyt rewolwingowy (odnawialny) – limit, który po spłacie można ponownie wykorzystać.', {'k': ['mezzanine', 'rewolwing', 'kredyt odnawialn']}),
 ('Łączenie spółek, wykupy LBO/MBO i synergia', 'Połączenie spółek wg KSH: przez przejęcie (spółka przejmowana wygasa) lub przez zawiązanie nowej spółki; przejęcie kontroli przez zakup akcji lub aktywów. Wykup lewarowany (LBO) – finansowany długiem zabezpieczonym aktywami celu; wykup menedżerski (MBO). Motywy: synergia (kosztowa, przychodowa, finansowa), korzyści skali, dywersyfikacja, wejście na nowe rynki. Badanie due diligence ocenia sytuację celu przed transakcją (por. Fuzja i przejęcie).', {'k': ['łączeni spółek', 'łączenie spółek', 'połączeni spółek', 'lbo', 'wykup lewarowan', 'wykup menedżersk', 'due diligence', 'synergi']}),
 ('Ryzyko walutowe i stopy procentowej w przedsiębiorstwie', 'Ryzyko walutowe – zmiana wartości przepływów w walutach obcych (transakcyjne, przeliczeniowe, ekonomiczne); ryzyko stopy procentowej – zmiana kosztu długu o zmiennym oprocentowaniu. Zabezpieczenia: hedging naturalny (koszty i przychody w tej samej walucie), forward, swap, opcje, IRS.', {'k': ['ryzyk walutow', 'ryzyko walutowe', 'ryzyka walutowego', 'ryzyk stopy procentowej', 'ryzyko stopy procentowej', 'hedging naturaln']}),
 ('Międzynarodowe aspekty finansów firmy', 'Finansowanie w walutach obcych, rachunki i kredyty walutowe, ceny transferowe w grupach kapitałowych, ryzyko kraju, rozliczenia handlu zagranicznego (akredytywa, inkaso), zabezpieczanie kursów, raje podatkowe i międzynarodowe standardy sprawozdawczości (MSSF/IFRS).', {'k': ['międzynarodow aspekt', 'mssf', 'ifrs', 'ryzyk kraju', 'ryzyko kraju']}),
 ('Inżynieria finansowa', 'Projektowanie nowych instrumentów i struktur finansowych (np. instrumentów pochodnych, sekurytyzacji, produktów strukturyzowanych) w celu zarządzania ryzykiem, obniżenia kosztów finansowania lub arbitrażu.', {'k': ['inżynieri finansow', 'inżynieria finansowa', 'produkt strukturyzowan']}),
 ('Analiza pozioma i pionowa (wstępna analiza sprawozdań)', 'Pozioma (dynamiki) – porównanie pozycji sprawozdań w czasie (zmiany bezwzględne i procentowe); pionowa (struktury) – udział pozycji w sumie bilansowej lub przychodach; metody czynnikowe (podstawień łańcuchowych, różnic cząstkowych) rozkładają zmianę wskaźnika na przyczyny.', {'k': ['analiz pozioma', 'analiza pozioma', 'analiz pionow', 'analiza pionowa', 'podstawień łańcuchow', 'różnic cząstkow']}),
 ('Modele wczesnego ostrzegania przed upadłością', 'Modele analizy dyskryminacyjnej łączące kilka wskaźników w jedną miarę zagrożenia upadłością – Z-score E. Altmana (1968), polskie modele (np. Mączyńskiej, Hołdy, Gajdki i Stosa).', {'k': ['altman', 'z-score', 'dyskryminac', 'wczesnego ostrzegania', 'zagrożeni upadłością']}),
 ('Wycena przedsiębiorstwa – metody', 'Majątkowe (wartość księgowa, odtworzeniowa, likwidacyjna aktywów netto), dochodowe (DCF – zdyskontowane przyszłe przepływy pieniężne + wartość rezydualna), porównawcze (mnożniki rynkowe P/E, EV/EBITDA, P/BV podobnych spółek), mieszane.', {'k': ['wycen przedsiębiorstw', 'wycena przedsiębiorstwa', 'wyceny przedsiębiorstwa', 'dcf', 'wartoś rezydualn', 'ev/ebitda', 'metod majątkow', 'metod porównawcz']}),
 ('Sprawozdanie z działalności (zarządu) i raportowanie niefinansowe', 'Sprawozdanie z działalności – opis sytuacji, wyników, ryzyk i planów, dołączane do sprawozdania finansowego. Duże jednostki raportują też kwestie niefinansowe (środowisko, pracownicy, prawa człowieka) – od 2024/2025 r. raportowanie zrównoważonego rozwoju wg dyrektywy CSRD i standardów ESRS (ESG).', {'u': 'zakres i terminy CSRD zmieniane w 2025 r. (pakiet „Omnibus”) – sprawdź aktualny stan', 'k': ['sprawozdani z działalności', 'sprawozdanie z działalności', 'sprawozdani zarządu', 'niefinansow', 'csrd', 'esrs', 'esg']}),
 ('Złota reguła finansowania (bankowa)', 'Zasada dopasowania terminów: majątek długoterminowy powinien być finansowany kapitałem długoterminowym, a „krótkim” pieniądzem można finansować tylko majątek krótkoterminowy (O. Hübner, 1854; por. Złota reguła bilansowa).', {'w': 'majątek długoterminowy / kapitał długoterminowy ≤ 1;  majątek krótkoterminowy / kapitał krótkoterminowy ≥ 1', 'k': ['złota reguła finansowania', 'złota zasada finansowania', 'reguł bankow', 'dopasowani terminów']}),
 ('Spółki osobowe i kapitałowe – wspólnicy', 'Osobowe: jawna, partnerska, komandytowa, komandytowo-akcyjna; kapitałowe: z o.o., prosta spółka akcyjna, akcyjna. W spółce komandytowej komplementariusz odpowiada za zobowiązania bez ograniczenia całym majątkiem, a komandytariusz – do wysokości sumy komandytowej; w S.K.A. akcjonariusz nie odpowiada za zobowiązania spółki.', {'k': ['komandytariusz', 'komplementariusz', 'suma komandytow', 'sumy komandytow', 'spółki osobow', 'spółki kapitałow']}),
 ("Analiza finansowa – istota, przedmiot i rodzaje", "Część analizy ekonomicznej przedsiębiorstwa (obok analizy techniczno-ekonomicznej i działalności gospodarczej) oceniająca sytuację majątkową, kapitałową, wynikową, płynność, sprawność i zadłużenie na podstawie sprawozdań finansowych. Rodzaje: ex post (retrospektywna) i ex ante (prognostyczna); wewnętrzna (dla zarządu) i zewnętrzna (dla banków, inwestorów); wstępna (sprawozdań) i szczegółowa (wskaźnikowa); kompleksowa i problemowa (np. tylko płynność).", {}),
 ("Materiały źródłowe analizy finansowej", "Podstawą analizy jest sprawozdanie finansowe (ustawa o rachunkowości): bilans, rachunek zysków i strat (wariant porównawczy – koszty według rodzajów, lub kalkulacyjny – koszty według funkcji: koszt sprzedanych produktów, sprzedaży, ogólnego zarządu), rachunek przepływów pieniężnych, zestawienie zmian w kapitale własnym i informacja dodatkowa; uzupełniają je sprawozdanie z działalności, opinia biegłego rewidenta, dane rynkowe i branżowe.", {}),
 ("Metody porównań w analizie finansowej", "Ocena wielkości przez zestawienie z punktem odniesienia: w czasie (dynamika, trend), w przestrzeni (z konkurentami, średnią branżową – benchmarking), z planem, normą lub wartością zalecaną (np. bieżąca płynność 1,2–2). Wymagają porównywalności danych: tych samych zasad wyceny, okresów i definicji wskaźników.", {}),
 ("Metody deterministyczne (kolejnych podstawień, różnic cząstkowych)", "Metody analizy czynnikowej rozkładające zmianę zjawiska na wpływ czynników powiązanych ścisłą zależnością funkcyjną (np. sprzedaż = ilość × cena; ROE = ROS × rotacja aktywów × mnożnik kapitałowy). Metoda kolejnych (łańcuchowych) podstawień zastępuje po kolei wartości bazowe czynników wartościami badanymi – suma wpływów równa się całkowitej zmianie, ale wynik zależy od kolejności podstawień. Metoda różnic cząstkowych mnoży zmianę czynnika przez pozostałe czynniki; inne odmiany to metoda funkcyjna i logarytmiczna.", {}),
 ("Metody stochastyczne w analizie finansowej", "Metody badające zależności niepewne (probabilistyczne) między zjawiskami, gdy nie łączy ich wzór, np. wpływ nakładów na reklamę na sprzedaż: współczynnik korelacji (siła i kierunek związku), regresja (oszacowanie funkcji zależności), analiza trendu. Wykorzystuje się je m.in. w prognozowaniu sprzedaży i w modelach wczesnego ostrzegania (analiza dyskryminacyjna).", {}),
 ("Model Du Ponta (piramida wskaźników)", "System wskaźników opracowany w koncernie DuPont (F. Donaldson Brown, ok. 1914 r.), rozkładający rentowność kapitału własnego na czynniki: rentowność sprzedaży (zysk netto / przychody), rotację aktywów (przychody / aktywa) i mnożnik kapitałowy (aktywa / kapitał własny – miara dźwigni). Pokazuje, czy wysoka ROE wynika z marży, efektywnego wykorzystania majątku czy z zadłużenia.", {"w": "ROE = ROS · (S/A) · (A/KW);  ROA = ROS · (S/A)"}),
 ("Analiza sprzedaży (wielkość, dynamika, struktura, opłacalność)", "Ocena przychodów ze sprzedaży: wielkości (wartościowo i ilościowo), dynamiki (indeksy jednopodstawowe i łańcuchowe, średnie tempo zmian), struktury (asortymentowej, terytorialnej, według odbiorców – np. analiza ABC wskazująca produkty dające większość przychodów) i opłacalności (marża pokrycia poszczególnych wyrobów). Zmianę wartości sprzedaży rozkłada się na wpływ ilości i ceny.", {}),
 ("Wskaźnik poziomu kosztów", "Relacja kosztów do przychodów (zwykle w %): ile groszy kosztów przypada na złotówkę przychodów. Spadek wskaźnika oznacza poprawę efektywności kosztowej; odwrotnością jest produktywność kosztów. GUS publikuje go dla przedsiębiorstw niefinansowych (zwykle ok. 95%).", {"w": "WPK = koszty / przychody · 100%"}),
 ("Marża pokrycia (marża brutto)", "Nadwyżka przychodów ze sprzedaży nad kosztami zmiennymi – kwota na pokrycie kosztów stałych i zysk. Jednostkowa: cena − jednostkowy koszt zmienny. Podstawa rachunku kosztów zmiennych, progu rentowności i decyzji o asortymencie (przy ograniczonych zasobach preferuje się wyroby o najwyższej marży na jednostkę zasobu). Nie mylić z zyskiem brutto ze sprzedaży w RZiS.", {"w": "MP = S − KZ;  jednostkowa: p − kz;  wskaźnik marży = MP / S"}),
 ("Wskaźniki wydajności gotówkowej (dynamiczna analiza płynności)", "Wskaźniki oparte na rachunku przepływów pieniężnych, uzupełniające statyczne wskaźniki płynności z bilansu: wydajność gotówkowa sprzedaży (przepływy operacyjne / przychody), aktywów (przepływy operacyjne / aktywa), zysku (przepływy operacyjne / zysk netto) oraz pokrycie zobowiązań przepływami. Pokazują, czy zysk zamienia się w gotówkę.", {"w": "WGS = CF operacyjne / przychody;  WGA = CF operacyjne / aktywa;  jakość zysku = CF operacyjne / zysk netto"}),
 ("Wskaźnik pokrycia odsetek (TIE)", "Miara zdolności do obsługi długu: ile razy zysk operacyjny (EBIT) pokrywa roczne odsetki. Niska wartość (np. poniżej 2–3) oznacza małą odporność na spadek zysków lub wzrost stóp procentowych. Uzupełnia go wskaźnik pokrycia obsługi długu (DSCR), uwzględniający także raty kapitałowe.", {"w": "TIE = EBIT / odsetki"}),
 ("Różnice kursowe", "Różnice wynikające ze zmiany kursu waluty między dniem ujęcia transakcji (np. otrzymania zaliczki, wystawienia faktury) a dniem zapłaty lub wyceny bilansowej. Zrealizowane powstają przy faktycznym wpływie lub wypływie waluty, niezrealizowane – przy wycenie na dzień bilansowy. Nadwyżka dodatnich różnic nad ujemnymi to przychód finansowy, nadwyżka ujemnych – koszt finansowy (art. 42 ustawy o rachunkowości).", {"k": ["różnic kursow", "różnice kursowe", "różnic kursowych", "różnicami kursowymi"]}),
 ("Analiza ex ante i ex post", "Analiza ex ante (łac. „przed zdarzeniem”) – prowadzona przed podjęciem decyzji, oparta na prognozach i planach (np. ocena projektu inwestycyjnego, analiza wariantów). Analiza ex post („po zdarzeniu”) – ocena dokonana po fakcie na podstawie rzeczywistych wyników (np. analiza sprawozdań finansowych za ubiegły rok); porównanie obu pozwala ocenić trafność decyzji.", {"k": ["ex ante", "ex post", "ex-ante", "ex-post", "a posteriori"]}),
]
